//! Wolfram golden replay: analytic rectangular-room acoustics.
//!
//! The fixture (`fixtures/wolfram-golden-v1.json`, generated by
//! `fixtures/room_modes_golden.wls` under Wolfram Engine 15.0.0) carries
//! three independent formulations: rigid-room eigenfrequencies with the
//! axial/tangential/oblique classification, the driven damped cosine modal
//! sum, and first-order image sources with wall-coefficient products. These
//! pin the numerical target the browser deployment replays; browser
//! automation itself remains a separate deployment concern.

use num_complex::Complex64;
use serde::Deserialize;
use sonium_roomsim::Point3D;
use sonium_roomsim::room_modes::{
    calculate_modal_pressure, calculate_room_modes, rectangular_image_sources,
};

const FIXTURE: &str = include_str!("../fixtures/wolfram-golden-v1.json");

#[derive(Debug, Deserialize)]
struct Entry {
    value: String,
    exact: String,
}

#[derive(Debug, Deserialize)]
struct Meta {
    engine: String,
    protocol: String,
}

#[derive(Debug, Deserialize)]
struct Mode {
    n: String,
    m: String,
    p: String,
    f: String,
    #[serde(rename = "type")]
    mode_type: String,
}

#[derive(Debug, Deserialize)]
struct Image {
    x: String,
    y: String,
    z: String,
    coeff: String,
    order: String,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    meta: Meta,
    modes: Vec<Mode>,
    values: std::collections::HashMap<String, Entry>,
    images: Vec<Image>,
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture = serde_json::from_str(FIXTURE).expect("valid Wolfram room-modes fixture");
    assert!(
        fixture.meta.engine.contains("Wolfram Engine"),
        "fixture must record its Wolfram provenance"
    );
    assert_eq!(fixture.meta.protocol, "audit-oracle-hermetic-v1");
    fixture
}

fn decimal(s: &str) -> f64 {
    s.parse().expect("golden is a decimal")
}

#[test]
fn room_mode_table_matches_wolfram() {
    let fixture = parse_fixture();
    let actual = calculate_room_modes(4.0, 3.0, 2.5, 343.0, 300.0, 2);
    assert_eq!(
        actual.len(),
        fixture.modes.len(),
        "mode count below 300 Hz at order 2"
    );
    for (index, (mode, golden)) in actual.iter().zip(&fixture.modes).enumerate() {
        assert_eq!(mode.indices[0].to_string(), golden.n, "mode {index} n");
        assert_eq!(mode.indices[1].to_string(), golden.m, "mode {index} m");
        assert_eq!(mode.indices[2].to_string(), golden.p, "mode {index} p");
        assert_eq!(mode.mode_type, golden.mode_type, "mode {index} type");
        let expected = decimal(&golden.f);
        let rel = ((mode.frequency - expected) / expected).abs();
        assert!(
            rel < 1e-12,
            "mode {index} frequency: Rust {} vs Wolfram {expected}",
            mode.frequency
        );
    }
}

#[test]
fn driven_modal_sum_matches_wolfram() {
    let fixture = parse_fixture();
    assert!(
        fixture.values["modal_re"]
            .exact
            .contains("driven damped cosine modal sum"),
        "modal golden must document the formulation"
    );
    let actual = calculate_modal_pressure(
        &Point3D::new(1.0, 2.0, 1.0),
        &Point3D::new(4.0, 1.0, 2.0),
        100.0,
        5.0,
        4.0,
        3.0,
        343.0,
        2,
        0.05,
    );
    let expected_re = decimal(&fixture.values["modal_re"].value);
    let expected_im = decimal(&fixture.values["modal_im"].value);
    assert!(
        (actual.re - expected_re).abs() < 1e-12,
        "Re(p): Rust {} vs Wolfram {expected_re}",
        actual.re
    );
    assert!(
        (actual.im - expected_im).abs() < 1e-12,
        "Im(p): Rust {} vs Wolfram {expected_im}",
        actual.im
    );
}

#[test]
fn first_order_image_sources_match_wolfram() {
    let fixture = parse_fixture();
    let reflections = [0.5, 0.6, 0.7, 0.8, 0.9, 0.4].map(Complex64::from);
    let mut actual = rectangular_image_sources(
        &Point3D::new(1.0, 1.0, 1.0),
        [5.0, 4.0, 3.0],
        reflections,
        1,
    );
    // Sort both sides identically so enumeration order is never asserted.
    actual.sort_by(|a, b| {
        a.2.cmp(&b.2)
            .then(a.0.x.total_cmp(&b.0.x))
            .then(a.0.y.total_cmp(&b.0.y))
            .then(a.0.z.total_cmp(&b.0.z))
    });
    assert_eq!(
        actual.len(),
        fixture.images.len(),
        "seven first-order images"
    );
    for (index, ((point, coeff, order), golden)) in actual.iter().zip(&fixture.images).enumerate() {
        assert_eq!(
            *order,
            decimal(&golden.order) as usize,
            "image {index} order"
        );
        for (axis, actual_coord, golden_coord) in [
            ("x", point.x, &golden.x),
            ("y", point.y, &golden.y),
            ("z", point.z, &golden.z),
        ] {
            let expected = decimal(golden_coord);
            assert!(
                (actual_coord - expected).abs() < 1e-12,
                "image {index} {axis}: Rust {actual_coord} vs Wolfram {expected}"
            );
        }
        let expected_coeff = decimal(&golden.coeff);
        assert!(
            (coeff.re - expected_coeff).abs() < 1e-12 && coeff.im.abs() < 1e-15,
            "image {index} coefficient: Rust {coeff} vs Wolfram {expected_coeff}"
        );
    }
}
